hist_id = 'bbd44e69cb8906b5d2bece4bdb8cf67c'
tool_id = 'toolshed.g2.bx.psu.edu/repos/iuc/deseq2/deseq2/2.11.40.8+galaxy3'

# First try to build the tool state to check parameter names
try:
    # Create a job to build the state first
    tool_inputs = {
        "select_data": {
            "how": "datasets_per_level",
            "rep_factorName": [
                {
                    "__index__": 0,
                    "factorName": "condition",
                    "rep_factorLevel": [
                        {
                            "__index__": 0,
                            "factorLevel": "KL",
                            "countsFile": {
                                "src": "hda",
                                "id": "f9cad7b01a472135f76e20ebf7438752"
                            }
                        },
                        {
                            "__index__": 1,
                            "factorLevel": "WL",
                            "countsFile": {
                                "src": "hda",
                                "id": "f9cad7b01a47213555982fd9e3ef7a2a"
                            }
                        }
                    ]
                }
            ]
        },
        "tximport": {
            "tximport_selector": "count"
        },
        "advanced_options": {
            "lfc_shrinkage_type": "apeglm",
            "outlier_filter_off": False,
            "auto_mean_filter_off": False,
            "prefilter_conditional": {
                "prefilter": ""
            }
        },
        "output_options": {
            "output_selector": "pdf",
            "alpha_ma": "0.05"
        }
    }

    # Try running with 21.01 format
    result = gi.tools.run_tool(
        history_id=hist_id,
        tool_id=tool_id,
        tool_inputs=tool_inputs,
        input_format='21.01'
    )
    print("Job submitted!")
