events.command:
python3 << 'PYEOF'
def safe_float(s):
    if s == 'NA' or s == '':
        return None
    return float(s)

# Check with raw p-value for both analyses
for fname, label in [('/workspace/deseq2_all6_results.tab', 'All 6'),
                      ('/workspace/deseq2_4samples_results.tab', '4 samples')]:
    count = 0
    with open(fname) as f:
        for line in f:
            parts = line.strip().split('\t')
            if not parts:
                continue
            basemean = safe_float(parts[1])
            log2fc = safe_float(parts[2])
            pvalue = safe_float(parts[4])

            if basemean is None or log2fc is None or pvalue is None:
                continue

            if pvalue < 0.05 and abs(log2fc) > 1 and basemean > 10:
                count += 1
    print(f"{label}: {count} DEGs (raw p-value < 0.05)")

# Also confirm padj-based counts
print("\n--- Using padj < 0.05 ---")
for fname, label in [('/workspace/deseq2_all6_results.tab', 'All 6'),
                      ('/workspace/deseq2_4samples_results.tab', '4 samples')]:
    count = 0
    with open(fname) as f:
        for line in f:
            parts = line.strip().split('\t')
            if not parts:
                continue
            basemean = safe_float(parts[1])
            log2fc = safe_float(parts[2])
            padj = safe_float(parts[5])

            if basemean is None or log2fc is None or padj is None:
                continue

            if padj < 0.05 and abs(log2fc) > 1 and basemean > 10:
                count += 1
    print(f"{label}: {count} DEGs (padj < 0.05)")
PYEOF

